        { taskID: 28, taskName: 'Client review', startDate: new Date('03/09/2025 08:00'), endDate: new Date('03/09/2025'), duration: 1, progress: '0', predecessor: '27FS', parentID: 1 },
        { taskID: 29, taskName: 'Project handover', startDate: new Date('03/10/2025 08:00'), endDate: new Date('03/10/2025'), duration: 0, predecessor: '28FS', parentID: 1 },
        { taskID: 30, taskName: 'Post-Project Review', startDate: new Date('03/10/2025 08:00'), endDate: new Date('03/10/2025 08:00'), duration: 0, progress: '0', predecessor: '29FS', parentID: 1 }
    ];
    taskFields = {
        id: 'taskID',
        name: 'taskName',
        startDate: 'startDate',
        duration: 'duration',
        progress: 'progress',
        dependency: 'predecessor',
        parentID: 'parentID'
    };
    timelineSettings = {
        timelineUnitSize: 70,
        topTier: {
            unit: 'Day',
            format: 'MMM dd, yyyy'
        },
        bottomTier: {
            unit: 'Hour',
            format: 'hh:mm a'
        }
    };
    dayWorkingTime = [{ from: 0, to: 24 }];
    getTimeZonesWithOffsets = () => {
        const now = new Date();
        const zones = Intl.supportedValuesOf ? Intl.supportedValuesOf('timeZone') : [
            'UTC', 'Asia/Calcutta', 'America/New_York', 'America/Los_Angeles', 'Europe/London',
            'Australia/Sydney', 'Asia/Tokyo', 'America/Chicago', 'America/Denver', 'America/Sao_Paulo'
        ];
        return zones.map(function (tz) {
            var formatter = new Intl.DateTimeFormat('en-US', {
                timeZone: tz,
                timeZoneName: 'longOffset'
            });
            // Use type assertion to bypass missing formatToParts in ES5 lib
            var parts = formatter.formatToParts(now);
            var offsetPart = parts.filter(function (part) { return part.type === 'timeZoneName'; })[0];
            var offset = offsetPart ? offsetPart.value : 'UTC+00:00';
            offset = offset.replace('GMT', 'UTC');
            return { id: tz, text: tz + ' (' + offset + ')' };
        });
    };
    getLocalTimeZoneWithOffset = () => {
        var timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
        var timeZonesWithOffsets = this.getTimeZonesWithOffsets();
        return timeZonesWithOffsets.find(function (zone) {
            return zone.id === timeZone;
        });
    };
    localTimezone = this.getLocalTimeZoneWithOffset().text;
    timeZones = this.getTimeZonesWithOffsets();
    timeZoneList = (args) => {
        if (args.value) {
            this.ganttInstance.timezone = args.value.toString().split(' (')[0];
            this.ganttInstance.refresh();
        }
        else {
            this.ganttInstance.timezone = null;
            this.ganttInstance.refresh();
        }
    };
    timelineUnit = (args) => {
        const unit = args.value;
        if (this.ganttInstance) {
            if (unit === 'Day') {
                this.ganttInstance.timelineSettings.topTier.unit = unit;
                this.ganttInstance.timelineSettings.bottomTier.unit = 'Hour';
                this.ganttInstance.timelineSettings.bottomTier.format = 'hh:mm a';
            }
            else if (unit === 'Week') {
                this.ganttInstance.timelineSettings.topTier.unit = unit;
                this.ganttInstance.timelineSettings.bottomTier.unit = 'Day';
                this.ganttInstance.timelineSettings.bottomTier.format = 'dd MMM';
            }
            else {
                this.ganttInstance.timelineSettings.topTier.unit = unit;
                this.ganttInstance.timelineSettings.bottomTier.unit = 'Day';
                this.ganttInstance.timelineSettings.bottomTier.format = 'dd';
            }
            this.ganttInstance.refresh();
        }
    };
    getPreviousTimeSpan = () => {
        return this.ganttInstance.previousTimeSpan();
    };
    getNextTimeSpan = () => {
        return this.ganttInstance.nextTimeSpan();
    };
    timelineData = ['Day', 'Week', 'Month'];
    render() {
        return (<div className="control-pane">
        <div className="control-section">
          <div className="content-wrapper">
            <div className="input-container" style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', position: 'relative' }}>
              <div className='timezone-label' style={{ display: 'flex', padding: '2px', alignItems: 'center' }}>
                <label htmlFor="timezonelist" style={{ fontSize: '15px', marginRight: '5px' }}>Time Zone:</label>
                <div style={{ padding: '2px', marginBottom: '5px' }}>
                  <ComboBoxComponent id="timezonelist" value={this.localTimezone} placeholder="Select Time Zone" change={this.timeZoneList} allowFiltering={true} filterType='Contains' dataSource={this.timeZones} style={{ width: '250px' }} popupWidth='350px' fields={{ value: 'id', text: 'text' }}/>
                </div>
              </div>
              <div className='timeline-input' style={{ display: 'flex', alignItems: 'center', position: 'absolute', right: '14px', }}>
                <div style={{ marginTop: '-5px', padding: '0 5px 0 5px' }}>
                  <ButtonComponent id='left-timespan-btn' onClick={this.getPreviousTimeSpan} className='timespan-btn'>
                    <span className='e-icons e-chevron-left-fill'></span>
                  </ButtonComponent>
                </div>
                <div style={{ marginBottom: '5px' }}>
                  <DropDownListComponent id="timeline" value={this.timelineSettings.topTier.unit} placeholder="Select timeline" change={this.timelineUnit} dataSource={this.timelineData}/>
                </div>
                <div style={{ marginTop: '-5px', padding: '0 5px 0 5px' }}>
                  <ButtonComponent id='right-timespan-btn' onClick={this.getNextTimeSpan} className='timespan-btn'>
                    <span className='e-icons e-chevron-right-fill'></span>
                  </ButtonComponent>
                </div>
              </div>
            </div>
          </div>
          <GanttComponent id='Timezone' dataSource={this.timezoneData} ref={gantt => this.ganttInstance = gantt} timelineSettings={this.timelineSettings} height='650px' taskbarHeight={25} rowHeight={46} timezone={this.localTimezone.split(' (')[0]} durationUnit='Hour' includeWeekend={true} treeColumnIndex={1} dateFormat='hh:mm a' dayWorkingTime={this.dayWorkingTime} taskFields={this.taskFields}>
            <ColumnsDirective>
              <ColumnDirective field='taskID' visible={false} width='80'></ColumnDirective>
              <ColumnDirective field='taskName' width='250'></ColumnDirective>
              <ColumnDirective field='startDate'></ColumnDirective>
              <ColumnDirective field='duration'></ColumnDirective>
              <ColumnDirective field='predecessor'></ColumnDirective>
              <ColumnDirective field='progress'></ColumnDirective>
            </ColumnsDirective>
            <Inject services={[Selection]}/>
          </GanttComponent>
        </div>

      </div>);
    }
}

const root = createRoot(document.getElementById('sample'));
root.render(<Timezone />);

